input.query:
SELECT txn_type, cost_type, count(*), sum(amount), min(amount), max(amount) FROM claim_txn GROUP BY 1,2 ORDER BY 1,2;
SELECT txn_type, count(*), min(written_premium), max(written_premium), min(exposure_units), max(exposure_units), sum(CASE WHEN effective_date<>cover_end_date THEN 1 ELSE 0 END) FROM premium_txn GROUP BY 1;
SELECT p.txn_type, p.effective_date, p.cover_end_date, t.inception_date, t.expiry_date, t.cancel_date FROM premium_txn p JOIN policy_term t USING(term_id) WHERE p.txn_type IN ('CANCEL','MTA') LIMIT 6;
